"""External RSS sampling and server counters around the measured worker phase."""
from __future__ import annotations

import json
import os
from pathlib import Path
import selectors
import subprocess
import sys
import threading
import time

import psutil


def server_counters(container):
    # The sole benchmark uses this owned container; counters are whole-container,
    # not per-statement. No unrelated connections are generated by this sampler.
    result = subprocess.run(
        ["docker", "exec", container, "sh", "-c",
         "cat /sys/fs/cgroup/cpu.stat /sys/fs/cgroup/memory.current /sys/fs/cgroup/memory.peak"],
        capture_output=True, text=True, timeout=5, check=True,
    )
    lines = result.stdout.splitlines()
    cpu = next(int(line.split()[1]) for line in lines if line.startswith("usage_usec "))
    return {"cpu_usec": cpu, "memory_current_bytes": int(lines[-2]),
            "memory_lifetime_peak_bytes": int(lines[-1])}


def message(process, phase, timeout=180):
    # Binary, unbuffered stdout: selectors never misses a line in TextIO buffers.
    with selectors.DefaultSelector() as selector:
        selector.register(process.stdout, selectors.EVENT_READ)
        if not selector.select(timeout):
            raise TimeoutError(f"Worker timed out waiting for {phase}")
        value = json.loads(process.stdout.readline())
    if value.get("phase") != phase:
        raise RuntimeError(f"Worker expected {phase}; received {value}")
    return value


def measure(job, env, container):
    adapter, kind, case, size = job
    process = subprocess.Popen(
        [sys.executable, env.get("FBFAST_BENCH_WORKER", str(Path(__file__).with_name("comparison_worker.py"))),
         adapter, kind, case, str(size)], env=env, stdin=subprocess.PIPE,
        stdout=subprocess.PIPE, stderr=subprocess.PIPE, bufsize=0,
    )
    stopped = threading.Event()
    rss = []
    watcher = None
    try:
        message(process, "ready")
        child = psutil.Process(process.pid)
        baseline_rss = child.memory_info().rss
        def sample():
            while not stopped.is_set():
                try:
                    rss.append(child.memory_info().rss)
                except psutil.NoSuchProcess:
                    break
                stopped.wait(0.005)
        before = server_counters(container)
        watcher = threading.Thread(target=sample, daemon=True)
        watcher.start()
        counter_start = time.perf_counter()
        process.stdin.write(b"continue\n")
        measured = message(process, "measured")
        rss.append(child.memory_info().rss)
        stopped.set()
        watcher.join()
        after = server_counters(container)
        counter_seconds = time.perf_counter() - counter_start
        process.stdin.write(b"continue\n")
        correctness = message(process, "validated")
        if process.wait(timeout=30):
            raise RuntimeError("Worker failed during final connection cleanup")
        # Restrict output to structured diagnostics; stderr may contain DSNs.
        stderr_bytes = len(process.stderr.read())
        return {**measured, "correctness": correctness, "sampled_peak_rss_bytes": max(rss),
                "rss_before_query_bytes": baseline_rss,
                "rss_at_result_bytes": rss[-1], "rss_sample_count": len(rss),
                "rss_interval_seconds": 0.005, "stderr_bytes": stderr_bytes,
                "server_cpu_seconds": (after["cpu_usec"] - before["cpu_usec"]) / 1e6,
                "server_counter_interval_seconds": counter_seconds,
                "server_before": before, "server_after": after}
    finally:
        stopped.set()
        if watcher is not None:
            watcher.join(timeout=1)
        if process.poll() is None:
            process.kill()
            process.wait()
        for pipe in (process.stdin, process.stdout, process.stderr):
            pipe.close()


def clean_environment(config, package):
    env = {key: value for key, value in os.environ.items()
           if not key.startswith(("FB_", "FIREBIRD", "DYLD_", "PYTHONPATH", "ISC_"))}
    env.update(FBFAST_BENCH_CONFIG=json.dumps(config), FBFAST_BENCH_PACKAGE=str(package))
    return env
